  $('#newp').onclick = async () => { const name = prompt('Project name'), key = prompt('Key'); if (name && key) try { const p = await api('POST', `/api/workspaces/${st.wsId}/projects`, { name, key }); st.pid = p.id; boot(); } catch (e) { fail(e); } };
